/*
 * prog59_rule110 – reproduced from the original binary
 *
 * The program expects two command‑line arguments:
 *   1. A binary string consisting only of the characters ‘0’ and ‘1’.
 *      Its length must be between 1 and 60 (inclusive).
 *   2. A positive integer N (1\u2264N\u2264200) that specifies how many
 *      generations of the elementary cellular automaton “Rule\u00a0110”
 *      have to be printed.
 *
 * If any of the above conditions is violated the program prints
 *   INVALID_INPUT
 * followed by a newline and exits with status 0 (the original binary
 * used `puts`, which adds the newline automatically).
 *
 * Otherwise the program prints N lines.  The first line is the input
 * pattern itself; each subsequent line is the next generation of the
 * automaton, computed with periodic (wrap‑around) boundary conditions.
 *
 * The implementation below follows the exact observable behaviour of
 * the original binary while being clear and idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN   60      /* maximum length of the binary string   */
#define MAX_STEPS 200     /* maximum number of generations to print */

/* Rule 110 lookup table.
 * Index = (left << 2) | (center << 1) | right   (bits are 0 or 1)
 * Value = next state (0 or 1)
 *
 * 111 -> 0
 * 110 -> 1
 * 101 -> 1
 * 100 -> 0
 * 011 -> 1
 * 010 -> 1
 * 001 -> 1
 * 000 -> 0
 */
static const int RULE110[8] = {
    0,  /* 000 */
    1,  /* 001 */
    1,  /* 010 */
    1,  /* 011 */
    0,  /* 100 */
    1,  /* 101 */
    1,  /* 110 */
    0   /* 111 */
};

/* Validate that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s)
{
    while (*s) {
        if (*s != '0' && *s != '1')
            return 0;
        ++s;
    }
    return 1;
}

/* Compute the next generation of a binary row using Rule 110.
 * The rows are treated as circular (periodic boundary conditions).
 */
static void next_generation(const char *cur, char *next, size_t len)
{
    size_t i;
    for (i = 0; i < len; ++i) {
        int left   = cur[(i + len - 1) % len] - '0';
        int center = cur[i]                 - '0';
        int right  = cur[(i + 1) % len]      - '0';
        int idx    = (left << 2) | (center << 1) | right;
        next[i] = (char)(RULE110[idx] + '0');
    }
    next[len] = '\0';
}

int main(int argc, char *argv[])
{
    /* ----- argument count check ----- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* ----- input string validation ----- */
    if (len == 0 || len > MAX_LEN || !is_binary_string(input)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- steps (generations) parsing ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || steps < 1) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;          /* the original program caps at 200 */

    /* ----- buffers for the two rows (current & next) ----- */
    char row[MAX_LEN + 1];
    char next[MAX_LEN + 1];

    strcpy(row, input);   /* initial configuration */

    /* ----- main loop: print and evolve ----- */
    for (long gen = 0; gen < steps; ++gen) {
        puts(row);                     /* prints the row and a newline */
        next_generation(row, next, len);
        strcpy(row, next);             /* swap buffers for the next iteration */
    }

    return 0;
}
